#!/bin/bash
set -euo pipefail

# Test: bin/init-gh.sh — gh CLI installer for Egregore (no GitHub App, no manual PAT)
# Generated by /qa on 2026-04-16 for dev/oguzhan/validate-pat-flow-oss-release
# Covers: pre-flight failure modes, URL parsing, slug rules, bash 3.2 compat,
#         JSON shape, INSTALL-GH.md content, source-level guards.

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
INIT="$SCRIPT_DIR/bin/init-gh.sh"
DOC="$SCRIPT_DIR/INSTALL-GH.md"

PASS=0
FAIL=0
pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; return 0; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; return 0; }

echo "Testing: bin/init-gh.sh"
echo

# ── File existence + shebang + exec bits ──────────────────────────

[ -f "$INIT" ] && pass "init-gh.sh exists" || fail "init-gh.sh missing"
[ -f "$DOC" ] && pass "INSTALL-GH.md exists" || fail "INSTALL-GH.md missing"

head -1 "$INIT" | grep -q '^#!/bin/bash' \
  && pass "shebang is #!/bin/bash" \
  || fail "wrong or missing shebang"

# ── bash 3.2 syntax check ─────────────────────────────────────────

/bin/bash -n "$INIT" 2>/dev/null \
  && pass "bash 3.2 syntax clean" \
  || fail "bash -n rejects the script"

# ── Source-level guards ───────────────────────────────────────────

# Look for actual mapfile invocation (skip matches in comments/docs)
! grep -qE '^[[:space:]]*mapfile[[:space:]]' "$INIT" \
  && pass "no mapfile invocation (bash 4+ only)" \
  || fail "uses mapfile — breaks on macOS default bash 3.2"

! grep -q 'readlink -f' "$INIT" \
  && pass "no readlink -f (GNU-only)" \
  || fail "uses readlink -f — not on BSD/macOS"

! grep -qE 'sed -i[^ ]* ' "$INIT" \
  && pass "no sed -i (BSD/GNU divergence)" \
  || fail "uses sed -i — syntax differs between BSD and GNU"

! grep -q 'date -d ' "$INIT" \
  && pass "no date -d (GNU-only)" \
  || fail "uses date -d — not on BSD/macOS"

! grep -q 'declare -A' "$INIT" \
  && pass "no associative arrays (bash 4+ only)" \
  || fail "uses declare -A — breaks on bash 3.2"

grep -q '^set -euo pipefail$' "$INIT" \
  && pass "set -euo pipefail at top" \
  || fail "missing set -euo pipefail"

! grep -q 'source .env' "$INIT" && ! grep -q '\. \./\.env' "$INIT" \
  && pass "never sources .env (per project convention)" \
  || fail "sources .env — use grep|cut per bin/ convention"

! grep -q '…' "$INIT" \
  && pass "no Unicode ellipsis (bash 3.2 parser issue)" \
  || fail "Unicode ellipsis present — bash 3.2 may include bytes in identifiers"

# ── Origin URL regex coverage ─────────────────────────────────────

test_regex() {
  local url="$1" expect_owner="$2" expect_repo="$3" label="$4"
  local owner="" repo=""
  if [[ "$url" =~ github\.com[:/]([^/]+)/([^/.]+)(\.git)?$ ]]; then
    owner="${BASH_REMATCH[1]}"; repo="${BASH_REMATCH[2]}"
  fi
  if [ "$owner" = "$expect_owner" ] && [ "$repo" = "$expect_repo" ]; then
    pass "regex: $label"
  else
    fail "regex: $label" "got owner=$owner repo=$repo, want $expect_owner/$expect_repo"
  fi
}

test_regex "git@github.com:owner/repo.git"             "owner"       "repo"     "ssh with .git"
test_regex "git@github.com:owner/repo"                 "owner"       "repo"     "ssh no .git"
test_regex "https://github.com/owner/repo.git"         "owner"       "repo"     "https with .git"
test_regex "https://github.com/owner/repo"             "owner"       "repo"     "https no .git"
test_regex "https://x-access-token:TOK@github.com/o/r.git" "o"        "r"        "https with token"
test_regex "ssh://git@github.com/owner/repo.git"       "owner"       "repo"     "ssh:// scheme"
test_regex "git@github.com:Curve-Labs/egregore.git"    "Curve-Labs"  "egregore" "dashed org"

# Known limitation: repos with dots in the name are not recognized. Flag it.
if [[ "https://github.com/owner/my.project.git" =~ github\.com[:/]([^/]+)/([^/.]+)(\.git)?$ ]]; then
  fail "regex: dotted repo name should NOT falsely match" "matched ${BASH_REMATCH[1]}/${BASH_REMATCH[2]}"
else
  pass "regex: dotted repo name handled (no false match — auto-adopt skipped)"
fi

# ── Slugify behavior ──────────────────────────────────────────────

slugify() {
  echo "$1" | tr '[:upper:]' '[:lower:]' | sed 's/[^a-z0-9-]/-/g; s/--*/-/g; s/^-//; s/-$//'
}

test_slug() {
  local in="$1" expect="$2" label="$3"
  local got="$(slugify "$in")"
  [ "$got" = "$expect" ] && pass "slug: $label" || fail "slug: $label" "got '$got', want '$expect'"
}

test_slug "My Team"              "my-team"              "spaces"
test_slug "Acme_Co!"             "acme-co"              "underscores + punct"
test_slug "   Trim Me   "        "trim-me"              "leading/trailing spaces"
test_slug "---already---dashy---" "already-dashy"       "collapse dashes + trim"
test_slug "ALLCAPS"              "allcaps"              "uppercase"
test_slug "Mix3d-42"             "mix3d-42"             "preserve alnum+dash"
test_slug "!!!"                  ""                     "all junk → empty"
test_slug "Curve-Labs"           "curve-labs"           "dashed"

# ── JSON output schema ────────────────────────────────────────────

# Validate that the embedded jq template produces the expected shape
SAMPLE_CONFIG="$(jq -n \
  --arg org_name "Acme" \
  --arg github_org "acme" \
  --arg memory_repo "https://github.com/acme/acme-memory.git" \
  --arg repo_name "acme" \
  --arg slug "acme" \
  --argjson repos '[]' \
  '{
    mode: "local",
    org_name: $org_name,
    github_org: $github_org,
    memory_repo: $memory_repo,
    repo_name: $repo_name,
    slug: $slug,
    repos: $repos,
    upstream_url: "https://github.com/egregore-labs/egregore.git"
  }')"

for key in mode org_name github_org memory_repo repo_name slug repos upstream_url; do
  echo "$SAMPLE_CONFIG" | jq -e "has(\"$key\")" >/dev/null \
    && pass "egregore.json has $key" \
    || fail "egregore.json missing $key"
done

[ "$(echo "$SAMPLE_CONFIG" | jq -r '.mode')" = "local" ] \
  && pass "egregore.json mode=local" \
  || fail "egregore.json mode is not local"

# State file schema
SAMPLE_STATE="$(jq -n \
  --arg github_username "oz" --arg github_name "Oz" --arg display_name "Oz" --arg email "" \
  '{github_username: $github_username, github_name: $github_name, display_name: $display_name,
    email: $email, onboarding_complete: false, usage_type: "founder_group",
    org_setup: true, github_configured: true, workspace_ready: true}')"

for key in github_username github_name display_name email onboarding_complete usage_type \
           org_setup github_configured workspace_ready; do
  echo "$SAMPLE_STATE" | jq -e "has(\"$key\")" >/dev/null \
    && pass ".egregore-state.json has $key" \
    || fail ".egregore-state.json missing $key"
done

[ "$(echo "$SAMPLE_STATE" | jq -r '.onboarding_complete')" = "false" ] \
  && pass "state: onboarding_complete=false (triggers /onboarding)" \
  || fail "state: onboarding_complete is not false"

# ── Pre-flight presence (source-level) ───────────────────────────

grep -q 'Missing required tool' "$INIT" \
  && pass "preflight: has missing-tool error path" \
  || fail "preflight: no explicit missing-tool error"

grep -qE 'for tool in.* gh ' "$INIT" \
  && pass "preflight: checks for gh" \
  || fail "preflight: does not check for gh"

grep -qE 'gh auth status' "$INIT" \
  && pass "preflight: runs gh auth status" \
  || fail "preflight: never runs gh auth status"

grep -q 'gh auth login' "$INIT" \
  && pass "preflight: can bootstrap gh auth login" \
  || fail "preflight: no gh auth login fallback"

# ── INSTALL-GH.md content ─────────────────────────────────────────

for phrase in "gh" "gh auth login" "bin/init-gh.sh" "egregore-labs/egregore" \
              "third-party" "INSTALL.md"; do
  grep -qi "$phrase" "$DOC" \
    && pass "INSTALL-GH.md mentions: $phrase" \
    || fail "INSTALL-GH.md missing mention: $phrase"
done

# ── ensureDevelop (parity gap vs npx) ─────────────────────────────

# This is a known HIGH finding from QA. The npx founder flow calls
# ensureDevelop() on the core repo. Our script doesn't. /save will fail
# against a repo with no develop branch. Track the gap with a failing test
# until the fix lands.
if grep -qE 'develop' "$INIT"; then
  pass "init-gh.sh handles develop branch"
else
  fail "init-gh.sh does NOT set up develop branch (QA finding: ensureDevelop parity gap)" \
    "npx's ensureDevelop must be ported; /save relies on origin/develop existing"
fi

# ── .env permissions regression ───────────────────────────────────

# 1. Prove the underlying risk: `grep -v > tmp; mv tmp ENV_FILE` without a
#    trailing chmod drops 0600 → 0644 because mv takes tmp's inode+mode.
ENVTMP="/tmp/init-gh-env-test.$$"
touch "$ENVTMP" && chmod 600 "$ENVTMP" && echo "KEEP=yes" > "$ENVTMP"
grep -v '^GITHUB_TOKEN=' "$ENVTMP" > "$ENVTMP.tmp" || true
echo "GITHUB_TOKEN=new" >> "$ENVTMP.tmp"
mv "$ENVTMP.tmp" "$ENVTMP"
RAW_PERMS="$(stat -f '%Lp' "$ENVTMP" 2>/dev/null || stat -c '%a' "$ENVTMP" 2>/dev/null || echo "???")"
[ "$RAW_PERMS" = "644" ] \
  && pass ".env mv risk demonstrated (644 without post-chmod)" \
  || fail ".env mv risk scenario yielded $RAW_PERMS (expected 644)"

# 2. Apply the fix (chmod 600 AFTER mv) and verify 0600 sticks.
chmod 600 "$ENVTMP"
FIXED_PERMS="$(stat -f '%Lp' "$ENVTMP" 2>/dev/null || stat -c '%a' "$ENVTMP" 2>/dev/null || echo "???")"
rm -f "$ENVTMP"
[ "$FIXED_PERMS" = "600" ] \
  && pass ".env post-mv chmod 600 restores mode" \
  || fail ".env post-mv chmod yielded $FIXED_PERMS (expected 600)"

# 3. Source-level: init-gh.sh must have `chmod 600` on ENV_FILE AFTER the mv,
#    not only at the initial `touch`.
if awk '
  /mv "\$tmp" "\$ENV_FILE"/ { seen_mv=1; next }
  seen_mv && /chmod 600 "\$ENV_FILE"/ { print "ok"; exit }
' "$INIT" | grep -q ok; then
  pass "init-gh.sh applies chmod 600 AFTER mv (replacement path safe)"
else
  fail "init-gh.sh does NOT chmod 600 after mv — token remains world-readable"
fi

# ── MED fixes: idempotency + robustness ──────────────────────────

# #2 egregore.json should be jq-merged on re-run, not clobbered
grep -q 'jq -s ..\[0\] \* \.\[1\]' "$INIT" \
  && pass "egregore.json merged on re-run (preserves user customizations)" \
  || fail "egregore.json not merged — re-run wipes telegram_group_link etc."

# #3 .egregore-state.json should preserve onboarding_complete=true across re-runs
grep -q 'EXISTING_ONBOARDED' "$INIT" \
  && pass "re-run preserves onboarding_complete=true" \
  || fail "re-run flips onboarding_complete back to false"

# Verify state jq uses --argjson (bool), not --arg (string)
grep -q -- '--argjson onboarding_complete' "$INIT" \
  && pass "onboarding_complete encoded as JSON bool (--argjson)" \
  || fail "onboarding_complete may be a string instead of bool"

# #4 upfront gh scope verification
grep -q "has_scope \"repo\"" "$INIT" \
  && pass "upfront check for repo scope" \
  || fail "no upfront check for repo scope"

grep -q 'gh auth refresh' "$INIT" \
  && pass "tells user how to add missing scope" \
  || fail "no remediation message for missing scopes"

# #5 invitee instructions don't reference --join (nonexistent mode)
! grep -q 'bin/init-gh.sh --join' "$INIT" \
  && pass "invitee instructions don't reference unimplemented --join" \
  || fail "invitee instructions still reference --join (not implemented)"

grep -q 'npx create-egregore join' "$INIT" \
  && pass "invitee instructions reference working npx join path" \
  || fail "invitee instructions missing working join path"

# The broken `gh repo clone && claude` path must NOT be in the invitee message
if grep -A 3 'Tell .* to run' "$INIT" | grep -q 'gh repo clone .* && .* claude'; then
  fail "invitee instructions still show broken 'gh repo clone && claude' path"
else
  pass "invitee instructions don't promise unsupported gh-only join path"
fi

# #6 hard-exit on core/memory clone failure
if grep -q 'if ! clone_via_gh "\$CORE_FULL"' "$INIT" \
   && grep -q 'if ! clone_via_gh "\$MEM_FULL"' "$INIT"; then
  pass "core + memory clone failures hard-exit (not silent continue)"
else
  fail "core/memory clone failures not hard-exits"
fi

grep -q 'Recovery:' "$INIT" \
  && pass "clone-failure error shows recovery steps" \
  || fail "clone-failure error has no recovery guidance"

# #1 rollback trap tracks created repos
grep -q 'CREATED_REPOS=(' "$INIT" \
  && pass "tracks created repos for rollback" \
  || fail "no CREATED_REPOS tracking"

grep -qE 'trap on_exit EXIT' "$INIT" \
  && pass "installs EXIT trap" \
  || fail "no EXIT trap for rollback"

# Every gh repo create success should append to CREATED_REPOS
CREATES="$(grep -cE 'gh repo create' "$INIT")"
APPENDS="$(grep -cE 'CREATED_REPOS\+=' "$INIT")"
# We have 4 `gh repo create` (core template, core fallback, memory, project)
# and should track all 4 on success.
[ "$APPENDS" -ge 4 ] \
  && pass "all 4 successful creates tracked ($APPENDS appends)" \
  || fail "only $APPENDS CREATED_REPOS appends — expected ≥4 (core template, core fallback, memory, project)"

# INSTALL_COMPLETE=1 must fire before the trap's condition
grep -q 'INSTALL_COMPLETE=1' "$INIT" \
  && pass "install-complete flag set at happy-path end" \
  || fail "no INSTALL_COMPLETE flag — trap fires even on success"

# Credential helper fix: multi-account gh + macOS keychain bug
# Without this, `gh auth switch` users see silent `git push` 403s because
# git's inherited global credential.helper (e.g. osxkeychain) serves a
# different account's token than the one gh is currently using.
grep -q 'configure_gh_creds' "$INIT" \
  && pass "configure_gh_creds function defined" \
  || fail "missing configure_gh_creds — multi-account gh users will see push failures"

# ── Ordering: ensure_develop must run AFTER egregore.json push ────

# If develop is created BEFORE egregore.json is pushed to main, develop lacks
# the config. Every /save branch (which is branched from develop) would then
# also lack egregore.json → session-start can't read org → skills fail.
CONFIG_PUSH_LINE="$(grep -n 'Pushed egregore.json to remote' "$INIT" | head -1 | cut -d: -f1)"
ENSURE_DEV_CALL_LINE="$(grep -n '^ensure_develop "\$EGREGORE_DIR"' "$INIT" | head -1 | cut -d: -f1)"
if [ -n "$CONFIG_PUSH_LINE" ] && [ -n "$ENSURE_DEV_CALL_LINE" ] && [ "$ENSURE_DEV_CALL_LINE" -gt "$CONFIG_PUSH_LINE" ]; then
  pass "ensure_develop called AFTER egregore.json push (develop has config)"
else
  fail "ensure_develop runs BEFORE egregore.json push — develop will lack egregore.json" \
    "config_push:$CONFIG_PUSH_LINE ensure_dev:$ENSURE_DEV_CALL_LINE"
fi

grep -q "credential.helper '!gh auth git-credential'" "$INIT" \
  && pass "repo-local credential.helper uses gh (honors gh auth switch)" \
  || fail "no !gh auth git-credential helper — keychain will serve wrong account"

grep -qE 'git -C .* config --local --replace-all credential.helper' "$INIT" \
  && pass "clears inherited global credential helpers per-clone" \
  || fail "does not clear inherited helpers — stale global helper can still win"

# ── Shell alias injection (npx parity) ────────────────────────────

grep -q 'install_shell_alias' "$INIT" \
  && pass "install_shell_alias function defined" \
  || fail "no install_shell_alias — npx parity gap"

grep -q 'claude start' "$INIT" \
  && pass "alias command uses 'claude start' (npx parity)" \
  || fail "alias command doesn't use 'claude start'"

grep -qE '\.zshrc|\.bashrc|\.bash_profile|\.profile|config.fish' "$INIT" \
  && pass "detects at least one shell profile" \
  || fail "no shell profile detection"

grep -q 'config/fish/config.fish' "$INIT" \
  && pass "handles fish shell profile path" \
  || fail "fish shell profile not handled"

grep -q 'alias %s=' "$INIT" || grep -q "alias %s=%s" "$INIT" \
  && pass "bash/zsh alias syntax emitted" \
  || fail "no bash/zsh alias line format"

grep -q "alias %s %s" "$INIT" \
  && pass "fish alias syntax emitted" \
  || fail "no fish alias line format (alias NAME 'CMD')"

# Idempotency: must remove old lines matching this dir / name before appending
if grep -A 5 'local tmp=' "$INIT" | grep -q 'grep -v -F -- "$dir"'; then
  pass "alias install removes old lines for same dir (idempotent)"
else
  fail "alias install may accumulate duplicate lines on re-run"
fi

# Must be called from clone_via_gh so every clone gets the helper configured
if grep -A 15 'clone_via_gh()' "$INIT" | grep -q 'configure_gh_creds'; then
  pass "clone_via_gh invokes configure_gh_creds after every clone"
else
  fail "clone_via_gh doesn't wire up gh credentials after clone"
fi

# ── Summary ───────────────────────────────────────────────────────

echo
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
